import { VoltAgent, Agent, createWorkflowChain } from '@voltagent/core';
import { honoServer } from '@voltagent/server-hono';
import { openai } from '@ai-sdk/openai';
import { z } from 'zod';

// Define schemas
const PayloadSchema = z.object({
  data: z.any().describe('The extracted structured JSON payload'),
});

const SummarySchema = z.object({
  summary: z.string().describe('A concise summary of the analyzed payload'),
});

// Define agents
const receiver = new Agent({
  id: 'receiver',
  name: 'Receiver Agent',
  model: openai('gpt-4o-mini'),
  instructions: 'Extract a structured JSON payload from the incoming text. Return only the JSON.',
});

const processor = new Agent({
  id: 'processor',
  name: 'Processor Agent',
  model: openai('gpt-4o-mini'),
  instructions: 'Analyze the extracted payload and generate a concise summary.',
});

// Create workflow chain
const workflow = createWorkflowChain({
  id: 'a2a-workflow',
  name: 'A2A Protocol Workflow',
  input: z.string(),
  output: SummarySchema,
})
  .andAgent(({ input }) => `Extract JSON from this text: ${input}`, receiver, {
    output: PayloadSchema,
  })
  .andAgent(({ data: payload }) => `Analyze this payload and summarize it: ${JSON.stringify(payload)}`, processor, {
    output: SummarySchema,
  });

// Initialize VoltAgent
const volt = new VoltAgent({
  agents: { receiver, processor },
  workflows: { 'a2a-workflow': workflow },
  server: honoServer({
    port: 3000,
    configureApp: (app) => {
      app.post('/api/process', async (c) => {
        try {
          const body = await c.req.json();
          const text = body.text;
          if (!text) {
            return c.json({ error: 'Missing text in request body' }, 400);
          }
          const result = await workflow.run(text);
          return c.json(result);
        } catch (error: any) {
          console.error('Workflow error:', error);
          return c.json({ error: error.message }, 500);
        }
      });
    },
  }),
});

console.log('Starting VoltAgent server on port 3000...');
volt.startServer().catch((err) => {
  console.error('Failed to start server:', err);
  process.exit(1);
});

